197	+function stBankY(x: number, z: number): number {
198	+  const ax = Math.abs(x), az = Math.abs(z), adz = Math.abs(z - SHZ), ar = Math.abs(ax - RV_X);
199	+  let y = LAND;
200	+  if (ax >= DR_X) {                                                 // Nguyễn Văn Linh / Võ Văn Kiệt
201	+    if (az <= DR_MED) y = Math.max(y, ROAD + 0.3);
202	+    else if (az <= DR_SIDE_IN) y = Math.max(y, ROAD + 0.03);
203	+    else if (az >= AX_SIDE.z0 && az <= AX_SIDE.z1) y = Math.max(y, ROAD + 0.2);
