267	+function stCr(a: number, b: number, c: number, d: number, dt0: number, dt1: number, dt2: number, t: number): number {
268	+  const t1 = ((b - a) / dt0 - (c - a) / (dt0 + dt1) + (c - b) / dt1) * dt1;
