273	+export function stSpinePoint(pts: [number, number][], t: number, out: { x: number; y: number }): void {
274	+  const l = pts.length, p = (l - 1) * t;
275	+  let i = Math.floor(p), w = p - i;
276	+  if (w === 0 && i === l - 1) { i = l - 2; w = 1; }
277	+  const p1 = pts[i], p2 = pts[i + 1];
278	+  const p0: [number, number] = i > 0 ? pts[i - 1] : [2 * pts[0][0] - pts[1][0], 2 * pts[0][1] - pts[1][1]];
279	+  const p3: [number, number] = i + 2 < l ? pts[i + 2] : [2 * pts[l - 1][0] - pts[l - 2][0], 2 * pts[l - 1][1] - pts[l - 2][1]];
