     1	import * as THREE from 'three';
     2	import { CONFIG } from '../../config';
     3	import { lerp } from '../../common/math';
     4	
     5	/* [config] Cầu sông Hàn: thông số ở CONFIG.songHan.
     6	   Tọa độ cục bộ: tâm trụ quay là gốc (x = 0 ở tim sông), group dời tới z = −1.080. Mét. */
     7	export const SH = CONFIG.songHan;
     8	
     9	let shLut: number[][] = null;
    10	export function shRoadY(x: number) {
    11	  if (Math.abs(x) <= SH.fixedStart) return SH.deckY;                   // nhịp quay phẳng tuyệt đối
    12	  const P = SH.roadProfile;
    13	  if (x <= P[0][0] || x >= P[P.length - 1][0]) return CONFIG.roadY;
    14	  if (!shLut) {
    15	    const c = new THREE.CatmullRomCurve3(P.map(([a, b]) => new THREE.Vector3(a, b, 0)), false, 'centripetal');
    16	    shLut = c.getPoints(3000).map((v) => [v.x, v.y]).sort((a, b) => a[0] - b[0]);
    17	  }
    18	  let lo = 0, hi = shLut.length - 1;
    19	  while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (shLut[mid][0] < x) lo = mid; else hi = mid; }
    20	  const [x0, y0] = shLut[lo], [x1, y1] = shLut[hi];
    21	  return Math.max(CONFIG.roadY, lerp(y0, y1, (x - x0) / Math.max(1e-6, x1 - x0)));
    22	}
