import { CONFIG } from 'D:/2026 - Tuan/danang-vite/src/config.ts';
import { stValid, stZoneAt, stGroundY, stSetGate } from 'D:/2026 - Tuan/danang-vite/src/explore/stroll/map.ts';
import { stBuildStaticMap, stBuildStructures, stSpawn } from 'D:/2026 - Tuan/danang-vite/src/explore/stroll/mapData.ts';
import { shRoadY } from 'D:/2026 - Tuan/danang-vite/src/bridges/song-han/profile.ts';
const map = stBuildStaticMap();
const B = CONFIG.stroll.bounds, SHZ = CONFIG.songHan.z;
// 1. water check at 0.1 m resolution for |x| in [255, 262.3]
let bad = 0;
for (let x = -262.3; x <= 262.3; x += 0.1) for (let z = B.z0; z <= B.z1; z += 0.25) {
  if (!stValid(map, x, z, Infinity)) continue;
  const id = stZoneAt(map, x, z).id;
  if (!/^(dragon|songHanW|songHanE|shSwing|love)$/.test(id)) { if (bad++ < 5) console.log('water', x, z, id); }
  if (id === 'dragon' && Math.abs(z) > 18.58 - 0.35 + 1e-9) console.log('dragon past rail', x, z);
  if (/songHan|shSwing/.test(id) && Math.abs(z - SHZ) > 6.24 - 0.35 + 1e-9) console.log('sh past rail', x, z);
}
console.log('water bad', bad);
// 2. continuity at 0.1 m around junctions
let worst = 0, wp: any = null;
const regions = [[320, 345, -22, 22], [-345, -320, -22, 22], [280, 300, SHZ - 9, SHZ + 9], [-300, -280, SHZ - 9, SHZ + 9], [255, 270, -82, -74], [55, 70, SHZ - 7, SHZ + 7]];
for (const [x0, x1, z0, z1] of regions) for (let x = x0; x <= x1; x += 0.05) for (let z = z0; z <= z1; z += 0.05) {
  if (!stValid(map, x, z, 0)) continue;
  for (const [dx, dz] of [[0.05, 0], [0, 0.05]]) {
    if (!stValid(map, x + dx, z + dz, 0)) continue;
    const d = Math.abs(stGroundY(map, x, z) - stGroundY(map, x + dx, z + dz));
    if (d > worst) { worst = d; wp = [x, z, stZoneAt(map, x, z).id, stZoneAt(map, x + dx, z + dz).id]; }
  }
}
console.log('worst step', worst, wp);
// 3. shRoadY at junctions
console.log('shRoadY 290', shRoadY(290), shRoadY(-290), shRoadY(289.9), shRoadY(285));
// 4. spawn
